var minimumOperations = function(grid) {
    const m = grid.length, n = grid[0].length;
    let operations = 0;
    for (let j = 0; j < n; ++j) {
        for (let i = 1; i < m; ++i) {
            if (grid[i][j] <= grid[i - 1][j]) {
                const target = grid[i - 1][j] + 1;
                operations += target - grid[i][j];
                grid[i][j] = target;
            }
        }
    }
    return operations;
};
